package cn.dreamingfish.launcher.mods;
import cn.dreamingfish.launcher.downloads.*;
import cn.dreamingfish.launcher.storage.LauncherJson;
import java.io.*;
import java.nio.file.Path;
import java.time.*;
import java.util.*;
public record ModLibraryEntry(UUID id,UUID taskId,ModSource source,String projectId,String versionId,String fileKey,String title,String fileName,List<String> gameVersions,List<String> loaders,FileDigest sourceDigest,long size,String sha256,Instant createdAt,List<ModDependency> dependencies,Path relativeFile) {
 public ModLibraryEntry {Objects.requireNonNull(id);Objects.requireNonNull(taskId);new ModFileRef(source,projectId,versionId,fileKey);Objects.requireNonNull(sourceDigest);Objects.requireNonNull(createdAt);if(fileName==null||fileName.isBlank()||fileName.length()>256||fileName.chars().anyMatch(Character::isISOControl)||!ModProtocol.ordinary(fileName)||size<0||size>2L*1024*1024*1024||sha256==null||!sha256.matches("[0-9a-f]{64}")||title!=null&&title.length()>512)throw new IllegalArgumentException("模组库记录字段无效");gameVersions=List.copyOf(gameVersions);loaders=List.copyOf(loaders);dependencies=List.copyOf(dependencies);String ext=fileName.toLowerCase(Locale.ROOT).endsWith(".litemod")?".litemod":".jar";if(!Path.of("mod-library/"+id+"/content"+ext).equals(relativeFile))throw new IllegalArgumentException("模组库路径无效");}
 public byte[] bytes()throws IOException{
  var map=new LinkedHashMap<String,Object>();map.put("schemaVersion",1);map.put("id",id.toString());map.put("taskId",taskId.toString());map.put("source",source.name());map.put("projectId",projectId);map.put("versionId",versionId);map.put("fileKey",fileKey);map.put("title",title);map.put("fileName",fileName);map.put("gameVersions",gameVersions);map.put("loaders",loaders);map.put("sourceDigest",Map.of("algorithm",sourceDigest.algorithm().name(),"hex",sourceDigest.hex()));map.put("size",size);map.put("sha256",sha256);map.put("createdAt",createdAt.toString());map.put("dependencies",dependencies);map.put("relativeFile",relativeFile.toString().replace('\\','/'));byte[] bytes=LauncherJson.write(map);if(bytes.length>128*1024)throw new TaskFailure("RECORD_TOO_LARGE","模组记录超过 128 KiB 上限");return bytes;
 }
 public static ModLibraryEntry parse(byte[] bytes)throws IOException{
  try{var n=LauncherJson.read(bytes,128*1024);var fields=new HashSet<String>();n.fieldNames().forEachRemaining(fields::add);if(!fields.equals(Set.of("schemaVersion","id","taskId","source","projectId","versionId","fileKey","title","fileName","gameVersions","loaders","sourceDigest","size","sha256","createdAt","dependencies","relativeFile"))||!n.path("schemaVersion").isInt()||n.path("schemaVersion").intValue()!=1)throw new IllegalArgumentException("模组记录结构无效");var d=n.path("sourceDigest");var digestFields=new HashSet<String>();d.fieldNames().forEachRemaining(digestFields::add);if(!d.isObject()||!digestFields.equals(Set.of("algorithm","hex")))throw new IllegalArgumentException("来源摘要结构无效");var hash=new FileDigest(FileDigest.Algorithm.valueOf(LauncherJson.text(d,"algorithm",16)),LauncherJson.text(d,"hex",128));var dependencies=new ArrayList<ModDependency>();if(!n.path("dependencies").isArray())throw new IllegalArgumentException("依赖记录无效");for(var value:n.path("dependencies")){var keys=new HashSet<String>();value.fieldNames().forEachRemaining(keys::add);if(!keys.equals(Set.of("kind","projectId","versionId","fileName")))throw new IllegalArgumentException("依赖字段无效");dependencies.add(new ModDependency(ModDependency.Kind.valueOf(LauncherJson.text(value,"kind",32)),ModProtocol.text(value,"projectId",128),ModProtocol.text(value,"versionId",128),ModProtocol.text(value,"fileName",256)));}
   return new ModLibraryEntry(TaskRequest.uuid(LauncherJson.text(n,"id",36)),TaskRequest.uuid(LauncherJson.text(n,"taskId",36)),ModSource.valueOf(LauncherJson.text(n,"source",16)),LauncherJson.text(n,"projectId",128),LauncherJson.text(n,"versionId",128),LauncherJson.text(n,"fileKey",64),ModProtocol.text(n,"title",512),LauncherJson.text(n,"fileName",256),ModProtocol.strings(n.path("gameVersions"),10000),ModProtocol.strings(n.path("loaders"),128),hash,ModProtocol.requiredNumber(n,"size"),LauncherJson.text(n,"sha256",64),Instant.parse(LauncherJson.text(n,"createdAt",64)),dependencies,Path.of(LauncherJson.text(n,"relativeFile",256)));
  }catch(RuntimeException error){throw new IOException("模组库记录损坏",error);}
 }
}
